import type { Device, ParameterDescriptor } from "./define";

/** The units the audio.js processor contract names. Any other is left out. */
const CONTRACT_UNITS = [
  "dB",
  "Hz",
  "s",
  "ms",
  "st",
  "cents",
  "oct",
  "deg",
  "rad",
  "m",
  "bpm",
  "LUFS",
  "dB/oct",
] as const;

/** A parameter as the audio.js processor contract 1.0 declares it in a processor's `params`. */
export type ContractParameter =
  | {
      curve?: "log";
      default: number;
      max: number;
      min: number;
      step?: number;
      type: "number";
      unit?: (typeof CONTRACT_UNITS)[number];
    }
  | { default: boolean; type: "bool" }
  | { default: string; type: "enum"; values: string[] };

/** Whether a range is a whole number of steps, which the contract asks of a `step`. */
function dividesRange(step: number, range: number) {
  const steps = range / step;
  return Math.abs(steps - Math.round(steps)) < 1e-6;
}

function contractParameter(parameter: ParameterDescriptor): ContractParameter {
  if (parameter.kind === "toggle") {
    return { default: parameter.default, type: "bool" };
  }
  if (parameter.kind === "choice") {
    return {
      default: parameter.default,
      type: "enum",
      values: parameter.options.map((option) => option.value),
    };
  }
  const { max, min, scale, step } = parameter;
  const unit = CONTRACT_UNITS.find((known) => known === parameter.unit);
  return {
    default: parameter.default,
    max,
    min,
    type: "number",
    ...(scale === "log" && { curve: "log" }),
    ...(step && dividesRange(step, max - min) && { step }),
    ...(unit && { unit }),
  };
}

/**
 * A device's parameters as the `params` of an audio.js processor, by parameter
 * id, in the order the device declares them: what a plugin host or an
 * `AudioWorklet` adapter reads, with no range written a second time.
 *
 * The contract has no labels, groups or formats, so they are left out, as are
 * a custom scale, a unit it does not name and a step that does not divide its
 * range.
 */
export function contractParams(
  device: Pick<Device<readonly ParameterDescriptor[]>, "parameters">
): Record<string, ContractParameter> {
  return Object.fromEntries(
    device.parameters.map((parameter) => [
      parameter.id,
      contractParameter(parameter),
    ])
  );
}

import { type ParameterScaleProp, resolveScale } from "./scale";

const clamp = (value: number, min: number, max: number) =>
  Math.max(min, Math.min(value, max));

import type { Tempo } from "../time/tempo";

/**
 * A device: an effect or an instrument as a set of named parameters, with no
 * interface and no audio in it. The same description feeds a panel (its knobs
 * and their ranges), an engine adapter (what to set on a node) and an agent
 * (which values it may ask for), so none of the three redefines a range.
 *
 * The state of a device is a plain object keyed by parameter id: numbers for
 * a continuous parameter, booleans for a toggle, the value of the picked
 * option for a choice. It is a value, never an
 * instance: a host stores it, saves it and sends it as it likes.
 */

/** A continuous parameter: a number in a range, on a scale, in steps. */
export interface NumberParameter {
  /** The value that reads as the neutral or centre, for bipolar controls (a pan, a detune). */
  anchor?: number;
  default: number;
  /** Prints a value for a readout. Defaults to the value with the unit and as many decimals as `step` has. */
  format?: (value: number) => string;
  id: string;
  kind?: "number";
  label: string;
  max: number;
  min: number;
  /** How the range maps onto a control's travel. `"log"` needs a positive `min`. @default "linear" */
  scale?: ParameterScaleProp;
  /** The grid values snap to, from `min`. Leave it out for a continuous parameter. */
  step?: number;
  /** The unit a value is in: `"dB"`, `"Hz"`, `"ms"`, `"%"`... shown after it. */
  unit?: string;
}

/** An on or off parameter: a bypass, a mode, an auto switch. */
export interface ToggleParameter {
  default: boolean;
  id: string;
  kind: "toggle";
  label: string;
}

/** One entry of a choice: the `value` that goes in the state and the `label` a panel shows. */
export interface ChoiceOption {
  label: string;
  value: string;
}

/** A pick from a short list: a waveform, a filter type, a mode. */
export interface ChoiceParameter {
  /** One of the `value`s of `options`. */
  default: string;
  id: string;
  kind: "choice";
  label: string;
  /** At least two, with distinct values. */
  options: readonly ChoiceOption[];
}

/** A parameter of a device: a number, a toggle or a choice. */
export type ParameterDescriptor =
  | NumberParameter
  | ToggleParameter
  | ChoiceParameter;

/** What a parameter holds: a number, a boolean or the value of a choice. */
export type ParameterValue = boolean | number | string;

/** The state of a device: each parameter's id to its value. */
export type DeviceState<
  Parameters extends
    readonly ParameterDescriptor[] = readonly ParameterDescriptor[],
> = {
  [Parameter in Parameters[number] as Parameter["id"]]: Parameter extends ToggleParameter
    ? boolean
    : Parameter extends ChoiceParameter
      ? Parameter["options"][number]["value"]
      : number;
};

/** Parameters gathered by what they do, under a name: a compressor's curve, its timing, its output. */
export interface DeviceGroup<Id extends string = string> {
  label: string;
  /** Parameter ids, in the order they are drawn. */
  parameters: readonly Id[];
}

/** What `defineDevice` takes: the device's id, name, description and parameters, and whether it is an instrument, takes a sidechain or adds latency. */
export interface DeviceDefinition<
  Parameters extends readonly ParameterDescriptor[],
> {
  /** What it does, in a line: what a catalog or an agent shows. */
  description: string;
  /** How a panel gathers the parameters, in the order drawn. A parameter in no group follows them. @default [] */
  groups?: readonly DeviceGroup<NoInfer<Parameters>[number]["id"]>[];
  /** A stable reverse-DNS id, such as `audioui.compressor`: a saved project stores this, not the panel that draws it. */
  id: string;
  /** Whether it processes sound or makes it. @default "effect" */
  kind?: "effect" | "instrument";
  /**
   * How long the device delays the sound it processes for a state, in seconds,
   * at a sample rate: what a host that compensates latency needs to know. A
   * look-ahead is a time and an oversampling filter a number of samples, hence
   * the sample rate. Leave it out for a device that adds none.
   */
  latency?: (state: DeviceState<Parameters>, sampleRate: number) => number;
  name: string;
  /**
   * What a note of this instrument is made of, as numbers with a range: a pitch
   * in hertz, a filter cutoff. An instrument that has them is played by a host
   * through `noteOn(note)` and by an agent through the `<id>_play` tool, which
   * is derived from them. Only an instrument has notes. `duration` is reserved.
   */
  note?: readonly NumberParameter[];
  parameters: Parameters;
  /**
   * Whether the device takes a second signal besides the one it processes, a
   * key that something else is listened to through: a compressor ducked by a
   * kick, a gate opened by a snare. The device does not carry the signal, only
   * the fact that it takes one, so a host knows to route something to its
   * engine's `sidechain` input and an agent can be told. @default false
   */
  sidechain?: boolean;
  /**
   * What its engine lets a host watch beyond what goes in and what comes out:
   * the readings it reports (`gainReduction`) and the points of its graph it
   * names in its `taps` (`modulator`, `wet`). A host draws a meter or a trace
   * for each one, and only for those. @default []
   */
  signals?: readonly DeviceSignalName[];
}

/**
 * What a device's engine lets a host watch of its sound beyond its input and
 * its output. `gainReduction` and `bandGainReduction` are read from its
 * `readings()`; `modulator` and `wet` are points of its graph it names in its
 * `taps`.
 */
export type DeviceSignalName =
  | "bandGainReduction"
  | "gainReduction"
  | "modulator"
  | "wet";

/** A parameter as an agent or a catalog reads it: JSON-safe, with no function in it. */
export interface ParameterDescription {
  default: ParameterValue;
  id: string;
  label: string;
  max?: number;
  min?: number;
  /** The values a choice takes. */
  options?: ChoiceOption[];
  /** `"custom"` for a scale given as functions: the range alone does not say how it travels. */
  scale?: "custom" | "linear" | "log";
  step?: number;
  type: "boolean" | "number" | "string";
  unit?: string;
}

/** A device as an agent or a catalog reads it. */
export interface DeviceDescription {
  description: string;
  id: string;
  kind: "effect" | "instrument";
  name: string;
  /** The numbers a note is made of, for an instrument that is played. */
  note?: ParameterDescription[];
  parameters: ParameterDescription[];
  /** Whether the device takes a key signal beside the one it processes. */
  sidechain?: boolean;
  /** What its engine lets a host watch beyond its input and its output. */
  signals?: DeviceSignalName[];
}

/** One parameter `apply` changed. */
export interface DeviceChange {
  /** `true` when the value asked for was outside the range or off the grid and was brought in. */
  adjusted: boolean;
  from: ParameterValue;
  id: string;
  to: ParameterValue;
}

/** One parameter `apply` did not change, and why. */
export interface DeviceRejection {
  id: string;
  reason:
    | "not a boolean"
    | "not a number"
    | "not one of the options"
    | "unknown parameter";
}

/** What `apply` returns: the new state, the changes made, and the changes refused with their reason. */
export interface DeviceApplied<State> {
  /** What changed, in the order asked. A value equal to the current one is not a change. */
  changes: DeviceChange[];
  rejected: DeviceRejection[];
  state: State;
}

/**
 * What a device reports about what it is doing right now, for a meter. Every
 * value is in dB, 0 or negative: the gain taken off the signal. A device reports
 * the readings it has: a compressor its gain reduction, a multiband device one
 * value per band. Read it per frame, as a meter does.
 */
export interface DeviceReadings {
  /** The gain taken off each band, in dB, 0 or negative, by band name. */
  bandGainReductionDb?: Record<string, number>;
  /** The gain taken off the signal, in dB, 0 or negative. */
  gainReductionDb?: number;
}

/**
 * What a host gives a device to drive: an engine, a view, a store. The device
 * knows nothing of it. `update` is called with each new state and must be cheap
 * to repeat; `dispose` releases what it holds.
 */
export interface DeviceBinding<State> {
  dispose: () => void;
  /** What the device is taking off right now. Optional: a device with no gain to report has none. */
  readings?: () => DeviceReadings;
  update: (state: State, context?: DeviceContext) => void;
}

/**
 * What the host knows and the device does not: the tempo a time parameter that
 * follows it is read against. Given with each `update`; a binding keeps the
 * last one it was given, and a host that has no tempo gives none.
 */
export interface DeviceContext {
  tempo: Tempo;
}

/** A defined device: its parameters, and everything that reads or changes a state of it, with no sound and no view. */
export interface Device<Parameters extends readonly ParameterDescriptor[]> {
  /**
   * Applies several changes at once and says what happened to each: the
   * answer a model can act on. A value out of range is brought in and marked
   * `adjusted`; an id the device does not have, or a value of the wrong type
   * (a string where a number goes), is `rejected` and the parameter is left
   * as it was, instead of being silently replaced by its default.
   */
  apply: (
    state: DeviceState<Parameters>,
    changes: Partial<Record<string, unknown>>
  ) => DeviceApplied<DeviceState<Parameters>>;
  /** `value` brought into the device's own bounds, snapped to the steps: what `set` stores. */
  clampValue: (id: Parameters[number]["id"], value: unknown) => ParameterValue;
  /** A state of the device's own defaults. A new object each time. */
  defaults: () => DeviceState<Parameters>;
  /** The inverse of `normalize`: the value at a position along the travel, snapped and clamped. */
  denormalize: (
    id: Parameters[number]["id"],
    position: number
  ) => ParameterValue;
  /** The device as JSON: what a catalog lists and an agent is told. */
  describe: () => DeviceDescription;
  readonly description: string;
  /** Prints a parameter's value for a readout, with its unit. */
  format: (id: Parameters[number]["id"], value: ParameterValue) => string;
  /** How a panel gathers the parameters. Empty for a device that declares no group. */
  readonly groups: readonly DeviceGroup[];
  readonly id: string;
  readonly kind: "effect" | "instrument";
  /** How long the device delays the sound for a state, in seconds, at a sample rate. 0 for a device that adds none. */
  latency: (state: DeviceState<Parameters>, sampleRate: number) => number;
  readonly name: string;
  /** Where a value sits along its parameter's travel, from 0 to 1, on its scale. A toggle is 0 or 1, a choice its place in the list. */
  normalize: (id: Parameters[number]["id"], value: ParameterValue) => number;
  /** What a note of the instrument is made of. Empty for an effect, and for an instrument that is not played by notes. */
  readonly note: readonly NumberParameter[];
  readonly parameters: Parameters;
  /** A state with every value in bounds: unknown ids dropped, missing ones defaulted, `NaN` replaced. */
  sanitize: (
    state: Partial<Record<string, unknown>>
  ) => DeviceState<Parameters>;
  /** A copy of `state` with one parameter changed to `value`, clamped. An id the device does not have returns `state` unchanged. */
  set: (
    state: DeviceState<Parameters>,
    id: string,
    value: unknown
  ) => DeviceState<Parameters>;
  /** Whether the device takes a second signal, a key, besides the one it processes. Its engine then has a `sidechain` input to connect it to. */
  readonly sidechain: boolean;
  /** What its engine lets a host watch beyond its input and its output: its readings and its taps, by name. Empty for a device that declares none. */
  readonly signals: readonly DeviceSignalName[];
}

/** Raised when a device is defined with parameters that cannot work. */
export class DeviceDefinitionError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "DeviceDefinitionError";
  }
}

const isNumber = (value: unknown): value is number =>
  typeof value === "number" && Number.isFinite(value);

function checkChoice(parameter: ChoiceParameter, where: string) {
  const values = parameter.options.map((option) => option.value);
  if (values.length < 2) {
    throw new DeviceDefinitionError(
      `${where}: a choice needs at least two options.`
    );
  }
  if (new Set(values).size !== values.length) {
    throw new DeviceDefinitionError(
      `${where}: two options have the same value.`
    );
  }
  if (!values.includes(parameter.default)) {
    throw new DeviceDefinitionError(
      `${where}: the default is not one of the options.`
    );
  }
}

function checkNumber(parameter: NumberParameter, where: string) {
  if (
    !(
      isNumber(parameter.min) &&
      isNumber(parameter.max) &&
      parameter.min < parameter.max
    )
  ) {
    throw new DeviceDefinitionError(
      `${where}: min must be below max, both finite.`
    );
  }
  if (
    !(
      isNumber(parameter.default) &&
      parameter.default >= parameter.min &&
      parameter.default <= parameter.max
    )
  ) {
    throw new DeviceDefinitionError(
      `${where}: the default is not within min and max.`
    );
  }
  if (
    parameter.step !== undefined &&
    !(isNumber(parameter.step) && parameter.step > 0)
  ) {
    throw new DeviceDefinitionError(`${where}: step must be above 0.`);
  }
  if (parameter.scale === "log" && parameter.min <= 0) {
    throw new DeviceDefinitionError(
      `${where}: a log scale needs a min above 0.`
    );
  }
}

function check(parameter: ParameterDescriptor, device: string) {
  const where = `${device}.${parameter.id || "(no id)"}`;
  if (!parameter.id.trim()) {
    throw new DeviceDefinitionError(`${device}: a parameter has no id.`);
  }
  if (!parameter.label.trim()) {
    throw new DeviceDefinitionError(`${where}: it has no label.`);
  }
  if (parameter.kind === "toggle") {
    if (typeof parameter.default !== "boolean") {
      throw new DeviceDefinitionError(
        `${where}: a toggle's default is true or false.`
      );
    }
  } else if (parameter.kind === "choice") {
    checkChoice(parameter, where);
  } else {
    checkNumber(parameter, where);
  }
}

/** Why a value cannot go in a parameter, or `undefined` when it can (it may still be brought into range). */
function refusal(
  parameter: ParameterDescriptor,
  asked: unknown
): DeviceRejection["reason"] | undefined {
  if (parameter.kind === "toggle") {
    return typeof asked === "boolean" ? undefined : "not a boolean";
  }
  if (parameter.kind === "choice") {
    return parameter.options.some((option) => option.value === asked)
      ? undefined
      : "not one of the options";
  }
  return isNumber(asked) ? undefined : "not a number";
}

/** Decimals a step prints: 0.1 is one, 0.25 is two, 1 is none. */
function decimalsOf(step: number | undefined) {
  if (!step || Number.isInteger(step)) {
    return 0;
  }
  return Math.min(6, (String(step).split(".")[1] ?? "").length);
}

/** A parameter as an agent or a catalog reads it. */
function describeParameter(
  parameter: ParameterDescriptor
): ParameterDescription {
  if (parameter.kind === "toggle") {
    return {
      default: parameter.default,
      id: parameter.id,
      label: parameter.label,
      type: "boolean",
    };
  }
  if (parameter.kind === "choice") {
    return {
      default: parameter.default,
      id: parameter.id,
      label: parameter.label,
      options: parameter.options.map(({ label, value }) => ({
        label,
        value,
      })),
      type: "string",
    };
  }
  const scale = parameter.scale ?? "linear";
  return {
    default: parameter.default,
    id: parameter.id,
    label: parameter.label,
    max: parameter.max,
    min: parameter.min,
    scale: typeof scale === "string" ? scale : "custom",
    step: parameter.step,
    type: "number",
    unit: parameter.unit,
  };
}

/** A group names parameters the device has, each in one group only. */
function checkGroups(
  groups: readonly DeviceGroup[],
  byId: ReadonlyMap<string, ParameterDescriptor>,
  device: string
) {
  const grouped = new Set<string>();
  for (const group of groups) {
    for (const id of group.parameters) {
      if (!byId.has(id)) {
        throw new DeviceDefinitionError(
          `${device}: the group ${group.label} names ${id}, which is not a parameter.`
        );
      }
      if (grouped.has(id)) {
        throw new DeviceDefinitionError(
          `${device}.${id}: this parameter is in two groups.`
        );
      }
      grouped.add(id);
    }
  }
}

/**
 * Defines a device from its parameters. The definition is checked once, here:
 * a duplicate id, a default outside its range or a log scale from zero throws
 * a `DeviceDefinitionError` that names the parameter, so a broken device never
 * reaches a panel or an agent.
 */
export function defineDevice<
  const Parameters extends readonly ParameterDescriptor[],
>(definition: DeviceDefinition<Parameters>): Device<Parameters> {
  const { parameters } = definition;
  if (!definition.id.trim()) {
    throw new DeviceDefinitionError("A device needs an id.");
  }
  const note = definition.note ?? [];
  const signals = definition.signals ?? [];
  if (note.length > 0 && definition.kind !== "instrument") {
    throw new DeviceDefinitionError(
      `${definition.id}: only an instrument has notes.`
    );
  }
  const noteIds = new Set<string>();
  for (const part of note) {
    check(part, `${definition.id}.note`);
    if (part.id === "duration") {
      throw new DeviceDefinitionError(
        `${definition.id}.note.duration: this id is reserved for how long a note lasts.`
      );
    }
    if (noteIds.has(part.id)) {
      throw new DeviceDefinitionError(
        `${definition.id}.note.${part.id}: two parts of a note have this id.`
      );
    }
    noteIds.add(part.id);
  }
  const byId = new Map<string, ParameterDescriptor>();
  for (const parameter of parameters) {
    check(parameter, definition.id);
    if (byId.has(parameter.id)) {
      throw new DeviceDefinitionError(
        `${definition.id}.${parameter.id}: two parameters have this id.`
      );
    }
    byId.set(parameter.id, parameter);
  }

  const groups: readonly DeviceGroup[] = definition.groups ?? [];
  checkGroups(groups, byId, definition.id);

  const clampValue = (id: string, value: unknown): ParameterValue => {
    const parameter = byId.get(id);
    if (!parameter) {
      return Number.NaN;
    }
    if (parameter.kind === "toggle") {
      return typeof value === "boolean" ? value : parameter.default;
    }
    if (parameter.kind === "choice") {
      return parameter.options.some((option) => option.value === value)
        ? (value as string)
        : parameter.default;
    }
    if (!isNumber(value)) {
      return parameter.default;
    }
    let next = clamp(value, parameter.min, parameter.max);
    if (parameter.step) {
      // The last step of the grid that is still within max: a grid that does
      // not end on max still ends inside it, on a step.
      const last = Math.floor(
        (parameter.max - parameter.min) / parameter.step + 1e-9
      );
      const steps = Math.min(
        last,
        Math.round((next - parameter.min) / parameter.step)
      );
      // Undo the float drift of `0.1 * 3`.
      next = Number(
        (parameter.min + steps * parameter.step).toFixed(
          decimalsOf(parameter.step) + 2
        )
      );
    }
    return next;
  };

  const defaults = () =>
    Object.fromEntries(
      parameters.map((parameter) => [parameter.id, parameter.default])
    ) as DeviceState<Parameters>;

  return {
    clampValue,
    defaults,
    description: definition.description,
    denormalize: (id, position) => {
      const parameter = byId.get(id);
      if (!parameter) {
        return Number.NaN;
      }
      if (parameter.kind === "toggle") {
        return position >= 0.5;
      }
      if (parameter.kind === "choice") {
        const last = parameter.options.length - 1;
        const index = Math.round(
          clamp(isNumber(position) ? position : 0, 0, 1) * last
        );
        return parameter.options[index]?.value ?? parameter.default;
      }
      const raw = resolveScale(parameter.scale ?? "linear").toValue(
        isNumber(position) ? position : 0,
        parameter.min,
        parameter.max
      );
      return clampValue(id, raw);
    },
    format: (id, value) => {
      const parameter = byId.get(id);
      if (!parameter) {
        return "";
      }
      if (parameter.kind === "toggle") {
        return value ? "On" : "Off";
      }
      if (parameter.kind === "choice") {
        return (
          parameter.options.find((option) => option.value === value)?.label ??
          ""
        );
      }
      if (!isNumber(value)) {
        return "";
      }
      if (parameter.format) {
        return parameter.format(value);
      }
      const text = value.toFixed(decimalsOf(parameter.step));
      return parameter.unit ? `${text} ${parameter.unit}` : text;
    },
    groups,
    id: definition.id,
    kind: definition.kind ?? "effect",
    latency: (state, sampleRate) =>
      Math.max(0, definition.latency?.(state, sampleRate) ?? 0),
    name: definition.name,
    normalize: (id, value) => {
      const parameter = byId.get(id);
      if (!parameter) {
        return Number.NaN;
      }
      if (parameter.kind === "toggle") {
        return value ? 1 : 0;
      }
      if (parameter.kind === "choice") {
        const index = parameter.options.findIndex(
          (option) => option.value === value
        );
        return index < 0 ? 0 : index / (parameter.options.length - 1);
      }
      return resolveScale(parameter.scale ?? "linear").toPosition(
        isNumber(value) ? value : parameter.default,
        parameter.min,
        parameter.max
      );
    },
    note,
    parameters,
    sidechain: definition.sidechain === true,
    signals,
    apply: (state, changes) => {
      const applied: DeviceChange[] = [];
      const rejected: DeviceRejection[] = [];
      let next = { ...state } as Record<string, ParameterValue>;
      for (const [id, asked] of Object.entries(changes)) {
        const parameter = byId.get(id);
        if (!parameter) {
          rejected.push({ id, reason: "unknown parameter" });
          continue;
        }
        const reason = refusal(parameter, asked);
        if (reason) {
          rejected.push({ id, reason });
          continue;
        }
        const to = clampValue(id, asked);
        const from = next[id] ?? parameter.default;
        if (to !== from) {
          applied.push({ adjusted: to !== asked, from, id, to });
          next = { ...next, [id]: to };
        }
      }
      return {
        changes: applied,
        rejected,
        state: next as DeviceState<Parameters>,
      };
    },
    describe: () => ({
      description: definition.description,
      id: definition.id,
      kind: definition.kind ?? "effect",
      name: definition.name,
      note: note.length > 0 ? note.map(describeParameter) : undefined,
      sidechain: definition.sidechain === true ? true : undefined,
      signals: signals.length > 0 ? [...signals] : undefined,
      parameters: parameters.map(describeParameter),
    }),
    sanitize: (state) => {
      const next = defaults() as Record<string, ParameterValue>;
      for (const parameter of parameters) {
        if (parameter.id in state) {
          next[parameter.id] = clampValue(parameter.id, state[parameter.id]);
        }
      }
      return next as DeviceState<Parameters>;
    },
    set: (state, id, value) => {
      if (!byId.has(id)) {
        return state;
      }
      return { ...state, [id]: clampValue(id, value) };
    },
  };
}

import { pink, white } from "@audio/synth-noise";
import { loadWorklet } from "../worklet/load";
import type { DeviceBinding, DeviceContext } from "./define";
import type { InstrumentBinding } from "./instrument";

/**
 * The points of an engine's graph a host may listen to beyond its input and
 * its output, by the names its device declares in `signals`. A host only
 * listens to them, with an analyser for a meter or a trace: connecting one
 * anywhere else plays it twice.
 */
export interface DeviceTaps {
  /** What moves the sound: the signal of an LFO, from -1 to 1, as it reaches what it modulates. */
  readonly modulator?: AudioNode;
  /** The processed sound alone, before the dry sound is mixed back in: a reverb's or a delay's tail. */
  readonly wet?: AudioNode;
}

/**
 * The engine of an effect on the Web Audio API: the binding of its state
 * (`update`, `dispose`, `readings`) between an input and an output. Every
 * `create<Name>Engine` of an effect returns one, with what it adds of its own.
 */
export interface EffectEngine<State> extends DeviceBinding<State> {
  /** Connect the signal to process here. */
  readonly input: AudioNode;
  /** Connect this to the destination, or to the next device. */
  readonly output: AudioNode;
  /** Resolves once the worklet it runs is in the graph, `false` where it cannot run. Until then it plays without it. */
  readonly ready?: Promise<boolean>;
  /** The input of the signal that drives it, on a device a sidechain keys. Only listened to, never heard. */
  readonly sidechain?: AudioNode;
  /** The points of its graph its device names in `signals`, for a host to listen to. */
  readonly taps?: DeviceTaps;
}

/**
 * The engine of an instrument: one voice, notes in, sound out. `noteOn`
 * starts a note or moves the held one to it, `noteOff` lets it go; a host
 * plays chords with one engine per note (`createPolyphony`).
 */
export interface InstrumentEngine<State, Note>
  extends InstrumentBinding<State, Note> {
  /** Connect this to the destination, or to the next device. */
  readonly output: AudioNode;
  /** Resolves once what it loads is in the graph. */
  readonly ready?: Promise<boolean>;
  /** The points of its graph its device names in `signals`, for a host to listen to. */
  readonly taps?: DeviceTaps;
}

/** What every `create<Name>Engine` is: an engine on a context, for the state it starts with and the host's tempo. */
export type EngineFactory<State, Engine> = (
  ctx: BaseAudioContext,
  state: State,
  context?: DeviceContext
) => Engine;

/** A worklet that takes over from the clean sound once it is in the graph. */
export interface WorkletStage {
  /** Sends both paths, the clean sound and the worklet's, on to `destination`. */
  connect: (destination: AudioNode) => void;
  dispose: () => void;
  /** The worklet, once it is in the graph: `null` until then, and for good where it cannot run. */
  readonly node: AudioWorkletNode | null;
  /** Resolves to `true` once the worklet plays, `false` where it cannot. */
  readonly ready: Promise<boolean>;
}

/**
 * A stage of an engine that runs a worklet: the sound passes clean while the
 * worklet loads, then fades over to it.
 *
 * ```
 * input → clean ─────────────────────┐
 *       → worklet (once loaded) → processed ─┴→ connect(destination)
 * ```
 *
 * `make` builds the worklet once its source is loaded, from the state the
 * engine holds then, unless the engine was disposed first. The fade is a
 * `setTargetAtTime` at `ramp` seconds. Two gains are made, the processed path
 * then the clean one.
 */
export function createWorkletStage(
  ctx: BaseAudioContext,
  {
    input,
    make,
    ramp,
    source,
  }: {
    /** What feeds both paths: the engine's input. */
    input: AudioNode;
    /** Makes the worklet, once loaded. */
    make: () => AudioWorkletNode;
    /** The time constant of the fade, in seconds. */
    ramp: number;
    /** The source of the worklet's processor, as `loadWorklet` takes it. */
    source: string;
  }
): WorkletStage {
  const processed = ctx.createGain();
  const clean = ctx.createGain();
  processed.gain.value = 0;
  clean.gain.value = 1;
  input.connect(clean);
  let node: AudioWorkletNode | null = null;
  let disposed = false;

  const ready = loadWorklet(ctx, source).then((ok) => {
    if (!ok || disposed) {
      return false;
    }
    node = make();
    input.connect(node).connect(processed);
    processed.gain.setTargetAtTime(1, ctx.currentTime, ramp);
    clean.gain.setTargetAtTime(0, ctx.currentTime, ramp);
    return true;
  });

  return {
    connect: (destination) => {
      clean.connect(destination);
      processed.connect(destination);
    },
    dispose: () => {
      disposed = true;
      clean.disconnect();
      processed.disconnect();
      node?.disconnect();
    },
    get node() {
      return node;
    },
    ready,
  };
}

/** How long after a path stops a worklet is still fed, in ms: its fade is over by then. */
export const FEED_RELEASE_MS = 120;

/** A connection a feed makes: `from` into `to`, at an output and an input of their own if given. */
export type FeedConnection = readonly [
  from: AudioNode,
  to: AudioNode,
  output?: number,
  input?: number,
];

/** Connections made while a path plays and taken away once it has faded out. */
export interface Feed {
  /** Clears what is still to be taken away. */
  dispose: () => void;
  /** Makes the connections at once when `on`; when off, takes them away `releaseMs` later, unless they are wanted again before. */
  set: (on: boolean) => void;
}

/**
 * Feeds a worklet only while the path it plays is heard: a worklet fed
 * nothing costs nothing. The connections are made on `set(true)` and taken
 * away `releaseMs` after `set(false)`, once the path has faded out, so
 * nothing is cut short.
 */
export function createFeed(
  connections: readonly FeedConnection[],
  releaseMs = FEED_RELEASE_MS
): Feed {
  let fed = false;
  let timer: ReturnType<typeof setTimeout> | undefined;
  return {
    dispose: () => clearTimeout(timer),
    set: (on) => {
      clearTimeout(timer);
      if (on && !fed) {
        for (const [from, to, output, input] of connections) {
          from.connect(to, output, input);
        }
        fed = true;
      } else if (!on && fed) {
        timer = setTimeout(() => {
          if (fed) {
            for (const [from, to] of connections) {
              from.disconnect(to);
            }
            fed = false;
          }
        }, releaseMs);
      }
    },
  };
}

/** How long a noise buffer lasts, in seconds: long enough that its loop is never heard. */
const NOISE_SECONDS = 2;
const noises = new WeakMap<BaseAudioContext, Map<NoiseColor, AudioBuffer>>();

/** The colors of noise a buffer is made in, as `@audio/synth-noise` makes them. */
export type NoiseColor = "pink" | "white";

/**
 * Two seconds of noise on a context, from `@audio/synth-noise` (seeded, its
 * peak at 0.9), made once per color and context and shared by everything that
 * plays it: a synth's noise source, a snare's rattle, the pink noise an
 * equalizer is heard through. A buffer is only read, so any number of sources
 * loop the same one.
 */
export function noiseBuffer(
  ctx: BaseAudioContext,
  color: NoiseColor = "white"
): AudioBuffer {
  const kept = noises.get(ctx) ?? new Map<NoiseColor, AudioBuffer>();
  noises.set(ctx, kept);
  const cached = kept.get(color);
  if (cached) {
    return cached;
  }
  const samples = (color === "pink" ? pink : white)(NOISE_SECONDS, {
    fs: ctx.sampleRate,
  });
  const buffer = ctx.createBuffer(1, samples.length, ctx.sampleRate);
  buffer.getChannelData(0).set(samples);
  kept.set(color, buffer);
  return buffer;
}

