/**
 * When a note starts or ends, and which note it is. `at` is a time of the
 * audio clock (a context's `currentTime`), now when there is none: a host
 * that schedules ahead gives the time each note falls at. `id` names the
 * note, so a host that plays several at once ends the right one: a `noteOff`
 * whose `id` is not the held note's lets nothing go.
 */
export interface NoteTiming {
  at?: number;
  id?: number | string;
}

/**
 * What a host gives an instrument to play: a `DeviceBinding` that also takes
 * notes. `Note` is the object the instrument's `note` descriptors describe,
 * a pitch in hertz and a cutoff for instance. `noteOn` starts a note, or moves
 * the one being held to it; `noteOff` lets it go. Both take an optional
 * `NoteTiming`: with none, now, and whichever note is held.
 */
export interface InstrumentBinding<State, Note> extends DeviceBinding<State> {
  noteOff: (timing?: NoteTiming) => void;
  noteOn: (note: Note, timing?: NoteTiming) => void;
}

/**
 * Plays a note for `seconds` on an instrument: `noteOn` now, `noteOff` when the
 * time is up. What the `<id>_play` tool asks of a host, in one call. Returns a
 * function that lets the note go early. Nothing here knows which clock it is:
 * the page's timer starts it, and a host with a sample-accurate clock of its own
 * keeps `noteOn` and `noteOff` and schedules them itself.
 */
export function playNote<Note>(
  instrument: Pick<InstrumentBinding<unknown, Note>, "noteOff" | "noteOn">,
  note: Note,
  seconds: number
): () => void {
  instrument.noteOn(note);
  let held = true;
  const release = () => {
    if (held) {
      held = false;
      instrument.noteOff();
    }
  };
  const timer = setTimeout(release, seconds * 1000);
  return () => {
    clearTimeout(timer);
    release();
  };
}

/**
 * What a host gives a device that takes a key signal: a `DeviceBinding` whose
 * engine has a second input, `sidechain`, that the key is connected to. It is
 * the shape of an audio engine, so it names no node type: `Input` is the node
 * of the host's audio API, such as an `AudioNode` on the Web Audio API.
 */
export interface SidechainBinding<State, Input> extends DeviceBinding<State> {
  /** Connect the signal that opens, closes or ducks the device here. */
  readonly sidechain: Input;
}

/**
 * Measure an engine against what its device claims. Everything runs in an
 * `OfflineAudioContext`, so a measurement hears exactly what the engine makes,
 * with no clock and no speakers; the measuring itself is audio.js's
 * (`@audio/measure-response`, `@audio/measure-latency`).
 *
 * It is made for the host that brings its own engine: give `measureResponse`
 * your engine's factory, a state and the curve of the device (such as
 * `equalizerCurve(state)`), and it says how far what your engine does is from
 * what the panel draws. A measurement, not a certification: the curve is the
 * device's own, and the tolerance is yours to choose.
 */

import latency from "@audio/measure-latency";
import response from "@audio/measure-response";
import type { EffectEngine, EngineFactory } from "./engine";

const SAMPLE_RATE = 48_000;
/** How long an impulse response is listened to for a frequency response, and for a latency, in seconds. */
const RESPONSE_SECONDS = 0.5;
const LATENCY_SECONDS = 0.3;
const RESPONSE_FREQUENCIES = [
  31, 62, 125, 250, 500, 1000, 2000, 4000, 8000, 12_000, 16_000,
];
/** A level under this is below what a 24-bit signal can show, so it is not compared. */
const AUDIBLE_FLOOR_DB = -50;

/** What a measurement needs of an engine: an effect's input and output, and what it loads. */
type MeasuredEngine = Pick<
  EffectEngine<unknown>,
  "dispose" | "input" | "output" | "ready"
>;

/** A unit impulse `seconds` long, at the measuring rate. */
const impulseOf = (seconds: number) => {
  const signal = new Float32Array(Math.round(seconds * SAMPLE_RATE));
  signal[0] = 1;
  return signal;
};

/** What comes out of an engine for `signal`, once what it loads is in: its impulse response for an impulse. */
async function renderThrough<State>(
  create: EngineFactory<State, MeasuredEngine>,
  state: State,
  signal: Float32Array
): Promise<Float32Array> {
  const ctx = new OfflineAudioContext(1, signal.length, SAMPLE_RATE);
  const buffer = ctx.createBuffer(1, signal.length, SAMPLE_RATE);
  buffer.getChannelData(0).set(signal);
  const source = ctx.createBufferSource();
  source.buffer = buffer;
  const engine = create(ctx, state);
  await engine.ready;
  source.connect(engine.input);
  engine.output.connect(ctx.destination);
  source.start();
  const rendered = await ctx.startRendering();
  engine.dispose();
  return rendered.getChannelData(0);
}

/** The level of a response at `hertz`, between the two bins around it. */
function levelAt(
  { db, freqs }: { db: Float32Array; freqs: Float32Array },
  hertz: number
) {
  const step = freqs[1] ?? 1;
  const below = Math.min(freqs.length - 2, Math.floor(hertz / step));
  const share = hertz / step - below;
  return (db[below] ?? 0) * (1 - share) + (db[below + 1] ?? 0) * share;
}

/** What a measurement of a frequency response found. */
export interface ResponseMeasurement {
  /** The frequency, in hertz, where the engine is furthest from the curve. */
  at: number;
  /** How far, in dB. 0 when no tested frequency had a curve audible enough to compare. */
  worstDb: number;
}

/**
 * How far an engine's frequency response is from `curve`, the gain in dB the
 * device draws at each frequency. The response is read from the engine's
 * impulse response, at 11 frequencies from 31 Hz to 16 kHz.
 */
export async function measureResponse<State>(
  create: EngineFactory<State, MeasuredEngine>,
  state: State,
  curve: (hertz: number) => number,
  frequencies: readonly number[] = RESPONSE_FREQUENCIES
): Promise<ResponseMeasurement> {
  const measured = response(
    await renderThrough(create, state, impulseOf(RESPONSE_SECONDS)),
    { fs: SAMPLE_RATE }
  );
  let worstDb = 0;
  let at = 0;
  for (const hertz of frequencies) {
    const wanted = curve(hertz);
    if (wanted < AUDIBLE_FLOOR_DB) {
      continue;
    }
    const gap = Math.abs(levelAt(measured, hertz) - wanted);
    if (gap > worstDb) {
      worstDb = gap;
      at = hertz;
    }
  }
  return { at, worstDb };
}

/** How long an engine delays a signal, in milliseconds: where what comes out of an impulse lines up with it. A host reports this to compensate it. */
export async function measureLatency<State>(
  create: EngineFactory<State, MeasuredEngine>,
  state: State
): Promise<number> {
  const reference = impulseOf(LATENCY_SECONDS);
  const recorded = await renderThrough(create, state, reference);
  return latency(recorded, reference, { fs: SAMPLE_RATE }).seconds * 1000;
}

/**
 * How a value maps onto a control's travel, and back. `toPosition` gives
 * where `value` sits along the travel, from 0 at `min` to 1 at `max`;
 * `toValue` is its inverse.
 */
export interface ParameterScale {
  toPosition: (value: number, min: number, max: number) => number;
  toValue: (position: number, min: number, max: number) => number;
}

/** A scale as a parameter takes it: `"linear"`, `"log"`, or a scale of your own. */
export type ParameterScaleProp = "linear" | "log" | ParameterScale;

const clamp = (value: number, min: number, max: number) =>
  Math.max(min, Math.min(value, max));

/** Even steps: the right feel for levels, times and anything heard in differences. */
export const LINEAR_SCALE: ParameterScale = {
  toPosition: (value, min, max) =>
    clamp((value - min) / (max - min || 1), 0, 1),
  toValue: (position, min, max) => min + clamp(position, 0, 1) * (max - min),
};

/**
 * Even ratios: the right feel for frequency, Q, ratios and times heard in
 * proportions. Needs a positive `min`; below that it falls back to linear.
 */
export const LOGARITHMIC_SCALE: ParameterScale = {
  toPosition: (value, min, max) => {
    if (!(min > 0 && max > min)) {
      return LINEAR_SCALE.toPosition(value, min, max);
    }
    return Math.log(clamp(value, min, max) / min) / Math.log(max / min);
  },
  toValue: (position, min, max) => {
    if (!(min > 0 && max > min)) {
      return LINEAR_SCALE.toValue(position, min, max);
    }
    return min * (max / min) ** clamp(position, 0, 1);
  },
};

/** The scale a parameter names: `"linear"` and `"log"` as the two above, a scale of your own as it is. */
export function resolveScale(scale: ParameterScaleProp): ParameterScale {
  if (scale === "log") {
    return LOGARITHMIC_SCALE;
  }
  return scale === "linear" ? LINEAR_SCALE : scale;
}

import {
  type Device,
  defineDevice,
  type ParameterDescriptor,
  type ParameterValue,
} from "./define";

/** The subset of JSON Schema the tools use: what OpenAI, Anthropic, MCP and the AI SDK all accept as an input schema. */
export interface JsonSchema {
  additionalProperties?: boolean;
  description?: string;
  items?: JsonSchema;
  maximum?: number;
  minimum?: number;
  minProperties?: number;
  multipleOf?: number;
  properties?: Record<string, JsonSchema>;
  type: "array" | "boolean" | "number" | "object" | "string";
  [key: string]: unknown;
}

/** How long a note lasts when a call does not say, and the shortest and longest it may ask for, in seconds. */
export const NOTE_DURATION = { default: 0.5, max: 30, min: 0.05 } as const;

/** What a tool's `run` returns: the state after the call, a summary for the model, and the note to play for a `<id>_play` call. */
export interface DeviceToolResult<State> {
  /** How long the note lasts, in seconds, for the call of a `<id>_play` tool. The host gives it to `playNote`. */
  duration?: number;
  /** The note to play, for the call of a `<id>_play` tool: its parts by id, in bounds. The host gives it to `noteOn`. */
  note?: Record<string, number>;
  /** The state after the call. The host stores it and drives its engine and view from it. */
  state: State;
  /** What happened, in a sentence a model can read back: the new values, what was adjusted, what was refused and why. */
  summary: string;
}

/** A tool a model can call to drive a device: agent-agnostic, with no SDK in it. */
export interface DeviceTool<State> {
  description: string;
  /** JSON Schema of the input. */
  inputSchema: JsonSchema;
  /** A valid tool name: letters, digits, underscore and hyphen. */
  name: string;
  /** Runs the call on `state`. Never throws on a model's input: a bad value is reported in the summary. */
  run: (state: State, input: unknown) => DeviceToolResult<State>;
}

const slug = (id: string) =>
  id.replace(/[^a-zA-Z0-9]+/g, "_").replace(/^_|_$/g, "");

function describeParameter(parameter: ParameterDescriptor): JsonSchema {
  if (parameter.kind === "toggle") {
    return {
      description: `${parameter.label}. true or false, ${parameter.default ? "on" : "off"} by default.`,
      type: "boolean",
    };
  }
  if (parameter.kind === "choice") {
    const values = parameter.options
      .map((option) => `"${option.value}" (${option.label})`)
      .join(", ");
    return {
      description: `${parameter.label}, one of ${values}, "${parameter.default}" by default.`,
      enum: parameter.options.map((option) => option.value),
      type: "string",
    };
  }
  const unit = parameter.unit ? ` ${parameter.unit}` : "";
  return {
    description: `${parameter.label}, from ${parameter.min}${unit} to ${parameter.max}${unit}, ${parameter.default}${unit} by default${
      parameter.scale === "log" ? ", on a log scale" : ""
    }.`,
    maximum: parameter.max,
    minimum: parameter.min,
    type: "number",
    ...(parameter.step ? { multipleOf: parameter.step } : {}),
  };
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

/**
 * The tools that drive a device, derived from its parameters: `<id>_set` takes
 * any of its parameters by id, `<id>_reset` puts some or all back to their
 * defaults. The ranges a model is told are the ones the device enforces, so a
 * hallucinated value is clamped and reported, not applied and not fatal, and
 * a parameter the device does not have is refused by name. Nothing here knows
 * which agent calls it.
 */
export function deviceTools<
  const Parameters extends readonly ParameterDescriptor[],
>(device: Device<Parameters>): DeviceTool<Record<string, ParameterValue>>[] {
  type State = Record<string, ParameterValue>;
  const base = slug(device.id);
  const properties = Object.fromEntries(
    device.parameters.map((parameter) => [
      parameter.id,
      describeParameter(parameter),
    ])
  );
  const label = (id: string) =>
    device.parameters.find((parameter) => parameter.id === id)?.label ?? id;
  const show = (id: string, value: ParameterValue) =>
    device.format(id as never, value);

  const set: DeviceTool<State> = {
    description: `Set parameters of the ${device.name}: ${device.description} Give only the parameters to change.`,
    inputSchema: {
      additionalProperties: false,
      minProperties: 1,
      properties,
      type: "object",
    },
    name: `${base}_set`,
    run: (state, input) => {
      if (!isRecord(input)) {
        return {
          state,
          summary: "Nothing changed: give an object of parameter values.",
        };
      }
      const result = device.apply(state as never, input);
      const parts = [
        ...result.changes.map(
          (change) =>
            `${label(change.id)}: ${show(change.id, change.from)} to ${show(change.id, change.to)}${
              change.adjusted ? " (brought into range)" : ""
            }`
        ),
        ...result.rejected.map(
          (rejection) => `${rejection.id}: refused, ${rejection.reason}`
        ),
      ];
      return {
        state: result.state as State,
        summary: parts.length
          ? parts.join("; ")
          : "Nothing changed: every value given is already set.",
      };
    },
  };

  const reset: DeviceTool<State> = {
    description: `Put parameters of the ${device.name} back to their defaults. Give the ids to reset, or none for all of them.`,
    inputSchema: {
      additionalProperties: false,
      properties: {
        ids: {
          description:
            "The ids of the parameters to reset. Leave it out to reset all.",
          items: { type: "string" },
          type: "array",
        },
      },
      type: "object",
    },
    name: `${base}_reset`,
    run: (state, input) => {
      const defaults = device.defaults() as State;
      const asked =
        isRecord(input) && Array.isArray(input.ids)
          ? input.ids.filter((id): id is string => typeof id === "string")
          : Object.keys(defaults);
      const changes = Object.fromEntries(
        asked.filter((id) => id in defaults).map((id) => [id, defaults[id]])
      );
      const result = device.apply(state as never, changes);
      const unknown = asked.filter((id) => !(id in defaults));
      const parts = [
        ...result.changes.map(
          (change) =>
            `${label(change.id)}: back to ${show(change.id, change.to)}`
        ),
        ...unknown.map((id) => `${id}: refused, unknown parameter`),
      ];
      return {
        state: result.state as State,
        summary: parts.length ? parts.join("; ") : "Already at the defaults.",
      };
    },
  };
  if (device.note.length === 0) {
    return [set, reset];
  }
  return [set, reset, playTool(device, base)];
}

/** `<id>_play`: the call that plays a note, from the descriptors of the instrument's note. */
function playTool<const Parameters extends readonly ParameterDescriptor[]>(
  device: Device<Parameters>,
  base: string
): DeviceTool<Record<string, ParameterValue>> {
  // The note is checked as any set of parameters is: in bounds, refused by name.
  const noteDevice = defineDevice({
    description: device.description,
    id: `${device.id}.note`,
    kind: "instrument",
    name: `${device.name} note`,
    parameters: device.note,
  });
  const properties: Record<string, JsonSchema> = {
    ...Object.fromEntries(
      device.note.map((part) => [part.id, describeParameter(part)])
    ),
    duration: {
      description: `How long the note lasts, in seconds, from ${NOTE_DURATION.min} to ${NOTE_DURATION.max}, ${NOTE_DURATION.default} by default.`,
      maximum: NOTE_DURATION.max,
      minimum: NOTE_DURATION.min,
      type: "number",
    },
  };
  return {
    description: `Play a note on the ${device.name} with the sound it has now. Give the parts of the note you want: the others take their defaults. It sounds for the duration, then lets go.`,
    inputSchema: {
      additionalProperties: false,
      properties,
      type: "object",
    },
    name: `${base}_play`,
    run: (state, input) => {
      const asked = isRecord(input) ? input : {};
      const { duration: askedDuration, ...parts } = asked;
      const applied = noteDevice.apply(noteDevice.defaults(), parts);
      const notes = [
        ...applied.changes.map(
          (change) =>
            `${noteDevice.parameters.find((part) => part.id === change.id)?.label ?? change.id}: ${noteDevice.format(change.id as never, change.to)}${
              change.adjusted ? " (brought into range)" : ""
            }`
        ),
        ...applied.rejected.map(
          (rejection) => `${rejection.id}: refused, ${rejection.reason}`
        ),
      ];
      let duration: number = NOTE_DURATION.default;
      if (askedDuration !== undefined) {
        if (
          typeof askedDuration === "number" &&
          Number.isFinite(askedDuration)
        ) {
          duration = Math.min(
            NOTE_DURATION.max,
            Math.max(NOTE_DURATION.min, askedDuration)
          );
          if (duration !== askedDuration) {
            notes.push(`duration: ${duration} s (brought into range)`);
          }
        } else {
          notes.push("duration: refused, not a number");
        }
      }
      return {
        duration,
        note: { ...applied.state } as Record<string, number>,
        state,
        summary: `Playing for ${duration} s${notes.length ? `: ${notes.join("; ")}` : "."}`,
      };
    },
  };
}
